import pandas as pd

def group_rates(df, threshold):
    """For each group: approval rate, TPR, FPR and PPV, approving when score >= threshold.

    df has columns group, score and repaid (True if the person repaid).
    Return a DataFrame indexed by group with columns approved, TPR, FPR, PPV.
    """
    rows = {}
    for g, part in df.groupby("group"):
        approve = part["score"] >= threshold
        rows[g] = {"approved": approve.mean(), "TPR": None, "FPR": None, "PPV": None}
    return pd.DataFrame(rows).T

exercises.tests:
import math
df = pd.DataFrame({
    "group":  ["A", "A", "A", "A", "A", "B", "B", "B", "B"],
    "score":  [0.9, 0.8, 0.7, 0.6, 0.4, 0.95, 0.66, 0.5, 0.3],
    "repaid": [True, True, False, True, False, True, False, True, False],
})
out = group_rates(df, 0.65)
assert list(out.index) == ["A", "B"], list(out.index)
assert list(out.columns) == ["approved", "TPR", "FPR", "PPV"], list(out.columns)
expected = {"A": [0.6, 2 / 3, 0.5, 2 / 3], "B": [0.5, 0.5, 0.5, 0.5]}
for g, values in expected.items():
    for col, want in zip(["approved", "TPR", "FPR", "PPV"], values):
        got = float(out.loc[g, col])
        assert math.isclose(got, want), f"group {g}, {col}: expected {want:.3f}, got {got:.3f}"
edge = group_rates(df, 0.66)
assert math.isclose(float(edge.loc["B", "FPR"]), 0.5), "approve when score >= threshold (a score equal to the threshold is approved)"

